{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "urgency",
  "per_column": [
    {
      "name": "acute_symptom_timeline",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Symptom onset speed (minutes-to-hours vs. days) is an antecedent clinical signal derivable from the presenting complaint. It plausibly precedes and predicts urgency without restating it or requiring outcome knowledge."
    },
    {
      "name": "urgent_diagnostic_or_intervention_trigger",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Categories like critical lab findings, urgent imaging, protocol/alert activation, and transfer to higher acuity are near-synonymous with the visit being urgent, and are determined during/after the urgency assessment. This effectively encodes the outcome rather than predicting it."
    },
    {
      "name": "treatment_intensity_or_escalation",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Treatment intensity (ICU admission, emergent IV meds, surgery, escalation) is a downstream response to urgency, knowable only after the clinical decision. Using it to predict urgency is post-outcome leakage, not an independent predictor."
    },
    {
      "name": "department_disposition",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Values bake the urgency label directly into the category (e.g., 'cardiology_with_acute_issue', 'general_practice_urgent', 'dermatology_routine'). This is a restatement of urgency conditioned on department rather than an outside predictor, and partly derives from the existing 'department' column."
    }
  ],
  "n_predictors": 1,
  "predictive_utility": 0.2,
  "rationale": "Only one column (acute_symptom_timeline) is a legitimate outside predictor of urgency. The other three encode diagnostic triggers, treatment escalation, and urgency-labeled dispositions that are downstream consequences of or synonymous with urgency, constituting leakage/restatement. As a set the added columns would inflate any model's apparent performance while offering little genuine pre-outcome predictive leverage; the timeline feature provides modest real signal."
}

